function lockedRows(rows) {
  return {
    [Symbol.iterator]() {
      console.log("lock");
      let i = 0;
      let locked = true;
      const unlock = () => {
        if (locked) console.log("unlock");
        locked = false;
      };
      return {
        next() {
          if (i >= rows.length) {
            unlock();
            return { value: undefined, done: true };
          }
          return { value: rows[i++], done: false };
        },
        return() {
          unlock();
          return { value: undefined, done: true };
        },
      };
    },
  };
}

for (const r of lockedRows(["A", "B", "C"])) if (r === "B") break;
