const PAGES = {
  start: { items: ["A", "B"], nextCursor: "p2" },
  p2: { items: ["C"], nextCursor: "p3" },
  p3: { items: ["D"], nextCursor: null },
};
let requests = 0;
const fetchPage = (cursor) => {
  requests++;
  return PAGES[cursor ?? "start"];
};

function paginate(fetchPage) {
  return {
    [Symbol.iterator]() {
      let buffer = [];
      let cursor = null;
      let started = false;
      return {
        next() {
          while (buffer.length === 0 && !(started && cursor === null)) {
            const page = fetchPage(cursor);
            started = true;
            buffer = [...page.items];
            cursor = page.nextCursor;
          }
          if (buffer.length === 0) return { value: undefined, done: true };
          return { value: buffer.shift(), done: false };
        },
      };
    },
  };
}

const [a, b] = paginate(fetchPage);
console.log(a, b, requests);
console.log([...paginate(fetchPage)].join(""));

