const data = [[450000, 120000], [980000], []];
const pages = {
  [Symbol.asyncIterator]() {
    let i = 0;
    return {
      async next() {
        if (i >= data.length) return { value: undefined, done: true };
        return { value: data[i++], done: false };
      },
    };
  },
};

async function sumAll(asyncIterable) {
  let total = 0;
  for await (const page of asyncIterable) {
    for (const amount of page) total += amount;
  }
  return total;
}

sumAll(pages).then((kobo) => console.log(`₦${kobo / 100}`));
